 async function mutate<T>(operation:DesktopRequest,label:string):Promise<T|undefined>{
  if(pending&&'commandId' in operation&&'commandId' in pending.request&&operation.commandId!==pending.request.commandId&&['send-message','submit-task','request-review','authorize-correction','create-project','save-connection'].includes(operation.type)){setError(t('Resolve the pending command before submitting another.'));return undefined;}
  setBusy(true);setError('');
  try{const result=await request<T>(operation);setPending(null);const current=await bootstrap();
   if(operation.type==='send-message'){const count=current?.conversations.find(c=>c.id===operation.conversationId)?.messageCount??1;setActiveId(operation.conversationId);setConversation(await request<ConversationDetail>({type:'conversation',conversationId:operation.conversationId,afterOrdinal:Math.max(0,count-16),limit:16}));setDraft(old=>old===operation.content?'':old);setDrafts(d=>({...d,[operation.conversationId]:''}));if(composerChoice)setChoices(old=>({...old,[operation.conversationId]:composerChoice}));setActivity('chat');setView('chat');bottom();}
   if(operation.type==='create-project'){setProjectDialog(false);setPendingProject(operation.id);setProjectName('');setProjectGrant(null);}
   if(operation.type==='submit-task'||operation.type==='authorize-correction'){setTaskOpen(false);setActivity('studio');setView('worker');setWorker(null);}
   if(operation.type==='save-connection')setConnectionDialog(false);
   return result;
  }catch(e){const message=String(e);setError(message);if(/not-confirmed|daemon-unavailable|binding-busy/.test(message))setPending({request:operation,label});return undefined;}finally{setBusy(false);}
 }

